// ── Verify the payload actually came from the app ──────────────────
//
// This webhook is a public URL. Unsigned, it is a way for anyone who learns
// it to send mail from the team's Gmail account to any address they like.
// The publishing lane needs this more than the notification lane does, not
// less: a spoofed notification is noise in a Discord channel, a spoofed
// publish is a message going out under the client's name.
//
// The app signs the RAW body with HMAC-SHA256 using N8N_PUBLISH_SECRET.

const crypto = require('crypto');

const SECRET_NAME = 'KOYA_PUBLISH_SECRET';

/**
 * Where the shared secret comes from, and why this is not a one-liner.
 *
 * Matches koya-proposal-delivery.json in 3/build: $env is unreachable on
 * n8n Cloud and is blocked by default on self-hosted instances, and TOUCHING
 * it THROWS rather than returning undefined. A bare $env.FOO would therefore
 * kill this node before the fail-closed branch below ever runs, turning a
 * clean 401 into an opaque 500. Both sources are tried, both are guarded.
 */
function readSecret(name) {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]);
  } catch (err) {
    // Env access is blocked on this instance. Not fatal — try Variables.
  }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return String($vars[name]);
  } catch (err) {
    // Neither source is readable. Handled by the fail-closed branch below.
  }
  return null;
}

const secret = readSecret(SECRET_NAME);
if (!secret) {
  throw new Error(
    `${SECRET_NAME} is not readable on this n8n instance. Set it as a Variable ` +
    '(Settings → Variables), or as an environment variable with ' +
    'N8N_BLOCK_ENV_ACCESS_IN_NODE=false. Its value must match N8N_PUBLISH_SECRET in the app. ' +
    'Refusing to send unverifiable mail.');
}

const headers = $input.item.json.headers || {};
const rawBody = $input.item.json.body;

const provided = headers['x-koya-signature'];
if (!provided) {
  throw new Error('Missing x-koya-signature header — refusing unsigned payload.');
}

const raw = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');

const a = Buffer.from(String(provided));
const b = Buffer.from(expected);
if (!(a.length === b.length && crypto.timingSafeEqual(a, b))) {
  throw new Error('Signature mismatch — refusing payload.');
}

const payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;

const recipients = Array.isArray(payload.recipients)
  ? payload.recipients.map(String).filter((e) => e.includes('@'))
  : [];

// An approved newsletter with nobody to send it to is a configuration
// problem, and it has to fail loudly. Returning ok here would write `sent`
// against a send that reached no inbox, which is the exact false success the
// whole queue design exists to prevent.
if (recipients.length === 0) {
  throw new Error('No recipients on the payload. Refusing to report a send that reached nobody.');
}
if (!payload.subject) {
  throw new Error('No subject line on the payload.');
}

return {
  json: {
    requestId: payload.requestId,
    idempotencyKey: String(payload.idempotencyKey || ''),
    subject: String(payload.subject),
    html: String(payload.html || ''),
    recipients,
    emittedAt: payload.emittedAt,
  },
};
